import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    dist = []
    index = 1
    for i in range(n):
        row = list(map(int, data[index:index+n]))
        dist.append(row)
        index += n

    INF = float('inf')
    dp = [[INF] * n for _ in range(1 << n)]

    # Starting at city 0 with only city 0 visited (mask has only 0th bit set)
    dp[1][0] = 0

    for mask in range(1 << n):
        for i in range(n):
            if dp[mask][i] == INF:
                continue
            for j in range(n):
                if not (mask & (1 << j)):
                    new_mask = mask | (1 << j)
                    new_dist = dp[mask][i] + dist[i][j]
                    if new_dist < dp[new_mask][j]:
                        dp[new_mask][j] = new_dist

    full_mask = (1 << n) - 1
    ans = INF
    for i in range(n):
        if dp[full_mask][i] != INF:
            total = dp[full_mask][i] + dist[i][0]
            if total < ans:
                ans = total

    print(ans)

if __name__ == "__main__":
    main()
